effect.shader:

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

//////////////////////////
    float Random(float x)
    {
    	return fract(sin(x * 123.456) * 23.4567 + sin(x * 345.678) * 45.6789 + sin(x * 456.789) * 56.789);
    }

    vec3 GetParticleColour(  vec3 vParticlePos,  float fParticleSize,  vec3 vRayDir )
    {		
    	vec2 vNormDir = normalize(vRayDir.xy);
    	float d1 = dot(vParticlePos.xy, vNormDir.xy) / length(vRayDir.xy);
    	vec3 vClosest2d = vRayDir * d1;

    	vec3 vClampedPos = vParticlePos;

    	vClampedPos.z = clamp(vClosest2d.z, vParticlePos.z - (fLength/60.0), vParticlePos.z + (fLength/60.0));

    	float d = dot(vClampedPos, vRayDir);

    	vec3 vClosestPos = vRayDir * d;

    	vec3 vDeltaPos = vClampedPos - vClosestPos;	

    	float fClosestDist = length(vDeltaPos) / fParticleSize;

    	float fShade = 	clamp(1.0 - fClosestDist, 0.0, 1.0);

    	fShade = fShade * exp2(-d * fDepthFade) * fBrightness;

    	return vec3(fShade);
    }

    vec3 GetParticlePos(  vec3 vRayDir,  float fZPos,  float fSeed )
    {
    	float fAngle = atan(vRayDir.x, vRayDir.y);
    	float fAngleFraction = fract(fAngle / (3.14 * 2.0));

    	float fSegment = floor(fAngleFraction * 121.0 + fSeed) + 0.5 - fSeed;
    	float fParticleAngle = fSegment / 121.0 * (3.14 * 2.0);
    	float fSegmentPos = fSegment / 121.0;

    	float fRadius = fMinDist + Random(fSegmentPos + fSeed) * (fMaxDist - fMinDist);

    	float tunnelZ = vRayDir.z / length(vRayDir.xy / fRadius);

    	tunnelZ += fZPos;

    	float fRepeat = fRepeatMin + Random(fSegmentPos + 0.1 + fSeed) * (fRepeatMax - fRepeatMin);

    	float fParticleZ = (ceil(tunnelZ / fRepeat) - 0.5) * fRepeat - fZPos;

    	return vec3( sin(fParticleAngle) * fRadius, cos(fParticleAngle) * fRadius, fParticleZ );
    }

    vec3 Starfield(  vec3 vRayDir,  float fZPos,  float fSeed )
    {	
    	vec3 vParticlePos = GetParticlePos(vRayDir, fZPos, fSeed);

    	return GetParticleColour(vParticlePos, fParticleSize, vRayDir);	
    }

    vec3 RotateX(  vec3 vPos,  float fAngle )
    {
        float s = sin(fAngle);
        float c = cos(fAngle);

        vec3 vResult = vec3( vPos.x, c * vPos.y + s * vPos.z, -s * vPos.y + c * vPos.z);

        return vResult;
    }

    vec3 RotateY(  vec3 vPos,  float fAngle )
    {
        float s = sin(fAngle);
        float c = cos(fAngle);

        vec3 vResult = vec3( c * vPos.x + s * vPos.z, vPos.y, -s * vPos.x + c * vPos.z);

        return vResult;
    }

    vec3 RotateZ(  vec3 vPos,  float fAngle )
    {
        float s = sin(fAngle);
        float c = cos(fAngle);

        vec3 vResult = vec3( c * vPos.x + s * vPos.y, -s * vPos.x + c * vPos.y, vPos.z);

        return vResult;
    }
//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);
    float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

    vec2 umefx;
    // umefx = acScreenNorm; 
    umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
    umefx.y*=acLayerSize.y/acLayerSize.x;

    umefx /= scale;
    umefx *= rot2m((0.0+angle)*0.0174533);
    umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
    vec2 scaleVec;
    scaleVec = vec2(scale*stretch.x,scale*stretch.y);
    umefx /= scaleVec;

    /////////////////////////

	vec4 fragColor;

    	vec2 vScreenPos = umefx;
    	// vec2 vScreenUV = umefx;
    	// vec2 vScreenPos = vScreenUV * 2.0 - 1.0;
    	// vScreenPos.x *= iResolution.x / iResolution.y;

    	vec3 vRayDir = normalize(vec3(vScreenPos, 1.0));
    	// vec3 vEuler = vec3(ROT.y, ROT.x, ROT.z) *0.01;
    	vec3 vEuler = ROT *0.01;
    	if(SPLITXYZ) { vEuler = vec3(ROT2, ROT3, ROT4); }
    	// if(SPLITXYZ) { vEuler = vec3(ROT3, ROT2, ROT4); }

    	vRayDir = RotateX(vRayDir, vEuler.y);
    	vRayDir = RotateY(vRayDir, vEuler.x);
    	// vRayDir = RotateX(vRayDir, vEuler.x);
    	// vRayDir = RotateY(vRayDir, vEuler.y);
    	vRayDir = RotateZ(vRayDir, vEuler.z);

    	float fShade = 0.0;
    	float a = 0.2;
    	float b = 10.0;
    	float c = 1.0;
    	float fZPos = 5.0 + iTime * c + sin(iTime * a) * b;
    	float fSeed = FSEED;

    	vec3 vResult = mix(vec3(0.0, 0.0, 0.0), vec3(0.0, 0.0, 0.0), vRayDir.y * 0.5 + 0.5);

    	for(int i=0; i<int(AMOUNT); i++)
    	{
    		vResult += Starfield(vRayDir, fZPos, fSeed);
    		fSeed += 1.234;
    	}

    	fragColor = vec4(sqrt(vResult),1.0);

	    vec4 factor;
	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
        float luminance = dot(fragColor.rgb, luminanceWeighting);
        vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
	    factor = mix(texColorX,gradmap,1.0);

    vec4 resultfinal;
      if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
      else if( blendMode==1 ) { factor *= hardness;
        vec4 c = factor + vec4(1.)*(1.-factor.a);
        resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
        // resultfinal = min(factor, texColor) * texColor.a; }
      else if( blendMode==2 ) { factor *= hardness; 
        resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          // resultfinal = max(factor, texColor) * texColor.a; }
      else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
      }
    }
